  /******************************************/
  /* Function Prefix                        */
  /******************************************/



/* tile parameters */
#define NUM_THREADS 256
#define SG0I 16
#define SG1J 16
#define TT0I 8
#define TT1J 8
#define MT0I (SG0I*TT0I)
#define MT1J (SG1J*TT1J)
#define VECTOR_WIDTH 8
#define GLOBAL_LOAD_VECTOR_WIDTH_A 8
#define GLOBAL_LOAD_VECTOR_WIDTH_B 8
#define GLOBAL_WRITE_VECTOR_WIDTH 8

/* DepthU parameters*/
#define CPSV (NUM_THREADS / MT0I * VECTOR_WIDTH)
#define LOCAL_SPLITU 1
#define UNROLL 32
#define LOCAL_DEPTHU (LOCAL_SPLITU*UNROLL)

/* other */
#define PAD 0
#define WORK_GROUP_MAPPING 8

/* num loads parallel and perpendicular to coalesced */
#define NLCA 1
#define NLCB 1
#define NLPA 2
#define NLPB 2

/* load sizes parallel and perpendicular to coalesced */
#define LSCA (MT0I/NLCA)
#define LSPA (LOCAL_DEPTHU/NLPA)
#define LSCB (LOCAL_DEPTHU/NLCB)
#define LSPB (MT1J/NLPB)
#define LVCA (LSCA/GLOBAL_LOAD_VECTOR_WIDTH_A)
#define LVCB (LSCB/GLOBAL_LOAD_VECTOR_WIDTH_B)
#define LVPA (LSPA/GLOBAL_LOAD_VECTOR_WIDTH_A)
#define LVPB (LSPB/GLOBAL_LOAD_VECTOR_WIDTH_B)
#define LDS_OFFSET_B 4096
#define LDS_NUM_ELEMENTS 16384
#define LDS_OFFSET_BLK 8192

/* global memory indices */
#define GLOBAL_D(IDX0I, IDX1J) (( ((int64_t)IDX0I)*strideD0I + ((int64_t)IDX1J)*strideD1J ))
#define GLOBAL_C(IDX0I, IDX1J) (( ((int64_t)IDX0I)*strideC0I + ((int64_t)IDX1J)*strideC1J ))
#define GLOBAL_OFFSET_A(IDX0I, IDXK) (( ((int64_t)IDX0I)*strideA0I + ((int64_t)IDXK)*strideAK ))
#define GLOBAL_OFFSET_B(IDXK, IDX1J) (( ((int64_t)IDXK)*strideBK + ((int64_t)IDX1J)*strideB1J ))

/* data types */
#define DATA_TYPE tensile_half
#define DEST_DATA_TYPE tensile_half
#define COMPUTE_DATA_TYPE tensile_half
#define MAGIC_DIV1(dividend, magicNumber, magicShift) ((uint64_t)(dividend) * magicNumber >> magicShift)

/* MAC's */
#define MAC(A,B,DST) DST += A*B
#define TYPE_MAC(MULA0,MULB0,DST0,MULA1,MULB1,DST1) \
  a_pk_fma[0] = MULA0; \
  a_pk_fma[1] = MULA1; \
  b_pk_fma[0] = MULB0; \
  b_pk_fma[1] = MULB1; \
  c_pk_fma[0] = DST0; \
  c_pk_fma[1] = DST1; \
  c_pk_fma = tensile_fmadd_half2(a_pk_fma, b_pk_fma, c_pk_fma); \
  DST0 = c_pk_fma[0]; \
  DST1 = c_pk_fma[1]; \
 
#define TYPE_MAC_WRITE(DST,ALPHA,REG) DST = (ALPHA)*(REG);

/* 8x8 micro-tile */
#define MAC_8x8\
  TYPE_MAC(rA[0],rB[0],rC[0+0*TT0I] , rA[1],rB[0],rC[1+0*TT0I]); \
  TYPE_MAC(rA[2],rB[0],rC[2+0*TT0I] , rA[3],rB[0],rC[3+0*TT0I]); \
  TYPE_MAC(rA[4],rB[0],rC[4+0*TT0I] , rA[5],rB[0],rC[5+0*TT0I]); \
  TYPE_MAC(rA[6],rB[0],rC[6+0*TT0I] , rA[7],rB[0],rC[7+0*TT0I]); \
  TYPE_MAC(rA[0],rB[1],rC[0+1*TT0I] , rA[1],rB[1],rC[1+1*TT0I]); \
  TYPE_MAC(rA[2],rB[1],rC[2+1*TT0I] , rA[3],rB[1],rC[3+1*TT0I]); \
  TYPE_MAC(rA[4],rB[1],rC[4+1*TT0I] , rA[5],rB[1],rC[5+1*TT0I]); \
  TYPE_MAC(rA[6],rB[1],rC[6+1*TT0I] , rA[7],rB[1],rC[7+1*TT0I]); \
  TYPE_MAC(rA[0],rB[2],rC[0+2*TT0I] , rA[1],rB[2],rC[1+2*TT0I]); \
  TYPE_MAC(rA[2],rB[2],rC[2+2*TT0I] , rA[3],rB[2],rC[3+2*TT0I]); \
  TYPE_MAC(rA[4],rB[2],rC[4+2*TT0I] , rA[5],rB[2],rC[5+2*TT0I]); \
  TYPE_MAC(rA[6],rB[2],rC[6+2*TT0I] , rA[7],rB[2],rC[7+2*TT0I]); \
  TYPE_MAC(rA[0],rB[3],rC[0+3*TT0I] , rA[1],rB[3],rC[1+3*TT0I]); \
  TYPE_MAC(rA[2],rB[3],rC[2+3*TT0I] , rA[3],rB[3],rC[3+3*TT0I]); \
  TYPE_MAC(rA[4],rB[3],rC[4+3*TT0I] , rA[5],rB[3],rC[5+3*TT0I]); \
  TYPE_MAC(rA[6],rB[3],rC[6+3*TT0I] , rA[7],rB[3],rC[7+3*TT0I]); \
  TYPE_MAC(rA[0],rB[4],rC[0+4*TT0I] , rA[1],rB[4],rC[1+4*TT0I]); \
  TYPE_MAC(rA[2],rB[4],rC[2+4*TT0I] , rA[3],rB[4],rC[3+4*TT0I]); \
  TYPE_MAC(rA[4],rB[4],rC[4+4*TT0I] , rA[5],rB[4],rC[5+4*TT0I]); \
  TYPE_MAC(rA[6],rB[4],rC[6+4*TT0I] , rA[7],rB[4],rC[7+4*TT0I]); \
  TYPE_MAC(rA[0],rB[5],rC[0+5*TT0I] , rA[1],rB[5],rC[1+5*TT0I]); \
  TYPE_MAC(rA[2],rB[5],rC[2+5*TT0I] , rA[3],rB[5],rC[3+5*TT0I]); \
  TYPE_MAC(rA[4],rB[5],rC[4+5*TT0I] , rA[5],rB[5],rC[5+5*TT0I]); \
  TYPE_MAC(rA[6],rB[5],rC[6+5*TT0I] , rA[7],rB[5],rC[7+5*TT0I]); \
  TYPE_MAC(rA[0],rB[6],rC[0+6*TT0I] , rA[1],rB[6],rC[1+6*TT0I]); \
  TYPE_MAC(rA[2],rB[6],rC[2+6*TT0I] , rA[3],rB[6],rC[3+6*TT0I]); \
  TYPE_MAC(rA[4],rB[6],rC[4+6*TT0I] , rA[5],rB[6],rC[5+6*TT0I]); \
  TYPE_MAC(rA[6],rB[6],rC[6+6*TT0I] , rA[7],rB[6],rC[7+6*TT0I]); \
  TYPE_MAC(rA[0],rB[7],rC[0+7*TT0I] , rA[1],rB[7],rC[1+7*TT0I]); \
  TYPE_MAC(rA[2],rB[7],rC[2+7*TT0I] , rA[3],rB[7],rC[3+7*TT0I]); \
  TYPE_MAC(rA[4],rB[7],rC[4+7*TT0I] , rA[5],rB[7],rC[5+7*TT0I]); \
  TYPE_MAC(rA[6],rB[7],rC[6+7*TT0I] , rA[7],rB[7],rC[7+7*TT0I]); \

#define MAC_8x8_BLK\
  TYPE_MAC(rA[0+TT0I],rB[0+TT1J],rC[0+0*TT0I] , rA[1+TT0I],rB[0+TT1J],rC[1+0*TT0I]); \
  TYPE_MAC(rA[2+TT0I],rB[0+TT1J],rC[2+0*TT0I] , rA[3+TT0I],rB[0+TT1J],rC[3+0*TT0I]); \
  TYPE_MAC(rA[4+TT0I],rB[0+TT1J],rC[4+0*TT0I] , rA[5+TT0I],rB[0+TT1J],rC[5+0*TT0I]); \
  TYPE_MAC(rA[6+TT0I],rB[0+TT1J],rC[6+0*TT0I] , rA[7+TT0I],rB[0+TT1J],rC[7+0*TT0I]); \
  TYPE_MAC(rA[0+TT0I],rB[1+TT1J],rC[0+1*TT0I] , rA[1+TT0I],rB[1+TT1J],rC[1+1*TT0I]); \
  TYPE_MAC(rA[2+TT0I],rB[1+TT1J],rC[2+1*TT0I] , rA[3+TT0I],rB[1+TT1J],rC[3+1*TT0I]); \
  TYPE_MAC(rA[4+TT0I],rB[1+TT1J],rC[4+1*TT0I] , rA[5+TT0I],rB[1+TT1J],rC[5+1*TT0I]); \
